    defs.push(`<path id="h${d}" d="${bitsPath(PAT_FONT[d])}"/>`);
    defs.push(`<path id="d${d}" d="${bitsPath(BIG_ROWS.map((i) => PAT_FONT[d][i]))}"/>`);
