  defs.push(`<polyline id="wv${k}" points="${pts.join(' ')}" fill="none" stroke="${YELLOW}" stroke-width="1.5" vector-effect="non-scaling-stroke"/>`);
  css.push(`@keyframes x${k}{from{transform:translateX(0)}to{transform:translateX(${-wv.period}px)}}.x${k}{animation:x${k} ${wv.dur}s steps(${wv.period}) infinite}`);
