const TITLE = 'ULTRA-SATISFACTORY as a four-channel tracker module';
const DESC = 'The editor screen of an Amiga-style music tracker, playing a song called ULTRA-SATISFACTORY. '
  + 'A grey embossed panel holds a stack of numeric fields with arrow buttons (POS, PATTERN, LENGTH 0004, ITEMS 0140, RECIPES 0211, BUILDINGS 0477, SAMPLE, PER MIN, CYCLE S, POWER MW), '
