  + 'Four black pattern windows labelled SMELTER, CONSTRUCTOR, ASSEMBLER and MANUFACTURER scroll blue note data under a fixed grey edit row. '
  + 'Each note is a machine finishing a craft cycle, so a 2 second recipe plays every 2 rows and one pattern is one minute of factory. A fat green-to-yellow VU bar per channel jumps on every note, and a yellow arrow pointer idles over the OVERCLOCK button.';

const fillPaths = [...fills].map(([colour, d]) => `<path d="${d}" fill="${colour}"/>`).join('');
const svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${W} ${H}" width="${W * 2}" height="${H * 2}" role="img" aria-labelledby="ttl dsc">
<title id="ttl">${xml(TITLE)}</title>
<desc id="dsc">${xml(DESC)}</desc>
<style>
${css.join('\n')}
</style>
<defs>
${defs.join('\n')}
</defs>
<rect width="${W}" height="${H}" rx="3" fill="#000"/>
<g transform="translate(${B} ${B})">
<path d="M0 0h${SW}v${SH}h${-SW}z" fill="${PANEL}"/>
${fillPaths}
<path d="${hi.join('')}" fill="${HI}"/>
<path d="${lo.join('')}" fill="${LO}"/>
${out.join('\n')}
</g>
</svg>
`;

fs.mkdirSync(path.dirname(OUT), { recursive: true });
fs.writeFileSync(OUT, svg);
console.log(`wrote ${path.relative(process.cwd(), OUT)}  ${(svg.length / 1024).toFixed(1)} KB  (${cellIds.size} cells, ${trackIds.size} hit tracks, loop ${LOOP_S}s)`);
